import{_ as t,o as l,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Month 2021: CephFS update","description":"","frontmatter":{"title":"Ceph Month 2021: CephFS update","date":"2021-06-23T00:00:00.000Z","updated":"2021-06-24T00:00:00.000Z","tags":["CephFS","Ceph Pacific版本","分布式存储","CephFS更新","CephFS功能改进"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_CephFS_update.md","filePath":"posts/2021/Ceph_Month_2021_-_CephFS_update.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Month_2021_-_CephFS_update.md"};function r(n,e,s,h,p,c){return l(),a("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-pacific版本更新及未来计划" tabindex="-1">会议主题：Ceph Pacific版本更新及未来计划 <a class="header-anchor" href="#会议主题-ceph-pacific版本更新及未来计划" aria-label="Permalink to &quot;会议主题：Ceph Pacific版本更新及未来计划&quot;">​</a></h4><h4 id="主讲人-patrick-donnelly-ceph-fs技术负责人" tabindex="-1">主讲人：Patrick Donnelly, Ceph FS技术负责人 <a class="header-anchor" href="#主讲人-patrick-donnelly-ceph-fs技术负责人" aria-label="Permalink to &quot;主讲人：Patrick Donnelly, Ceph FS技术负责人&quot;">​</a></h4><h4 id="会议时间-待定" tabindex="-1">会议时间：待定 <a class="header-anchor" href="#会议时间-待定" aria-label="Permalink to &quot;会议时间：待定&quot;">​</a></h4><h4 id="会议地点-线上" tabindex="-1">会议地点：线上 <a class="header-anchor" href="#会议地点-线上" aria-label="Permalink to &quot;会议地点：线上&quot;">​</a></h4><h4 id="主要内容" tabindex="-1">主要内容： <a class="header-anchor" href="#主要内容" aria-label="Permalink to &quot;主要内容：&quot;">​</a></h4><ol><li><p><strong>Pacific版本成就</strong></p><ul><li><strong>多文件系统支持稳定性提升</strong>：现在创建文件系统更加简单，自动化程度提高。</li><li><strong>MDS自动扩展器</strong>：根据文件系统需求自动启动和停止MDS。</li><li><strong>Ceph FS Top工具</strong>：管理员可以监控文件系统的使用情况，收集性能统计信息。</li><li><strong>Ceph FS Shell</strong>：一个简单的Python实用程序，允许在文件系统上执行命令，无需使用FUSE或内核。</li><li><strong>快照计划管理模块</strong>：允许在Ceph FS上按计划创建和保留快照。</li><li><strong>NFS网关支持</strong>：通过NFS管理器模块，可以创建NFS集群来导出Ceph FS。</li><li><strong>内核客户端加密支持</strong>：正在进行中，部分功能已实现。</li></ul></li><li><p><strong>性能和稳定性提升</strong></p><ul><li><strong>API设置最小客户端版本</strong>：确保客户端连接到集群的兼容性。</li><li><strong>多MDS文件系统扫描</strong>：现在支持在多个活动MDS的情况下进行扫描。</li><li><strong>内核客户端支持Messenger V2</strong>：通过内核挂载选项启用。</li><li><strong>异步创建和删除支持</strong>：提高操作效率。</li></ul></li><li><p><strong>多站点和生态系统改进</strong></p><ul><li><strong>快照镜像工具</strong>：支持基于快照的远程集群复制。</li><li><strong>Kubernetes CSI环境支持</strong>：改进与Kubernetes的集成。</li><li><strong>Ceph FS Token Windows客户端</strong>：类似于Ceph FUSE，提供Windows系统上的访问。</li></ul></li><li><p><strong>未来计划（Quincy版本）</strong></p><ul><li><strong>异步rmdir、link和rename支持</strong>：提高性能。</li><li><strong>异步元数据操作支持</strong>：正在进行中。</li><li><strong>MDS滚动升级支持</strong>：简化升级过程。</li><li><strong>libcephfs SQLite</strong>：一个新的客户端，允许在Ceph FS上使用SQLite数据库。</li><li><strong>MDS内存目标</strong>：优化MDS的内存使用。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续改进和开发Ceph FS的各项功能。</li><li>收集社区反馈，特别是关于Ceph FS Top工具和Ceph FS Shell的反馈。</li><li>推动Quincy版本的新功能开发，包括异步操作支持和MDS滚动升级。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>感谢所有参与者的参与。</li><li>请查看会议链接中的后续活动日历。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的详细内容和博客文章将在稍后分发。</li><li>欢迎随时提问和提供反馈。</li></ul>',13)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
